#include <cstdio>
#include <iostream>
#include <cmath>
#include <cfloat>
#define INF 1000000000
using namespace std;

double absolute(double n){
    return n >= 0 ? n : -n;
}

int find_closest(int x, int y, int b){
    double target_ratio = static_cast<double>(x) / y;
    int lower_bound=0, upper_bound=1000000;
    for(int i=0; i<25; i++){
        int mid = (lower_bound + upper_bound) / 2;
        if (static_cast<double>(mid) / b < target_ratio)
            lower_bound = mid;
        else
            upper_bound = mid;
    }
    int best_a;
    double min_diff=DBL_MAX;
    for(int a=lower_bound-10; a<=upper_bound+10; a++){
        double diff = absolute(static_cast<double>(a)/b - target_ratio);
        if(diff < min_diff){
            min_diff = diff;
            best_a = a;
        }
    }
    return best_a;
}

int main(){
    int x,y,n;
    scanf("%d %d %d",&x,&y,&n);
    int best_a, best_b;
    double min_difference=DBL_MAX;
    for(int b=1; b<=n; b++){
        int a = find_closest(x,y,b);
        double current_diff = absolute(static_cast<double>(a)/b - static_cast<double>(x)/y);
        if(current_diff < min_difference){
            min_difference = current_diff;
            best_a = a;
            best_b = b;
        }
    }
    printf("%d/%d\n", best_a, best_b);
    return 0;
}
